"""The company section: who we are, philosophy, FAQ and the technical glossary."""
import re
from html import escape as esc

WHY = 'Πιστεύουμε ότι ένας χώρος μπορεί να αλλάξει τον τρόπο που ζεις. Να σου δώσει περισσότερο φως, περισσότερη ελευθερία, περισσότερες δυνατότητες. Γι’ αυτό δημιουργούμε κατοικίες που ξεκινούν από τον άνθρωπο και δίνουν ουσιαστικό νόημα σε κάθε τετραγωνικό.'


def subnav(active, links):
    return '<nav class="subnav wrap" aria-label="Η εταιρεία μας">' + ''.join(
        f'<a href="{u}"' + (' aria-current="page"' if u == active else '') + f'>{t}</a>' for u, t in links) + '</nav>'


def render(page, intro, eyebrow, head, more, btn, pic, steps, faq, basefaq, paths, finalcta, links, root):
    # Who we are
    how = [('Καταλαβαίνουμε πώς θέλεις να ζεις', 'Πριν σχεδιάσουμε τοίχους, καταλαβαίνουμε τις ανάγκες σου. Πώς ζεις σήμερα, τι σε περιορίζει και τι θέλεις να αλλάξει.'),
           ('Δίνουμε μορφή στην ιδέα', 'Αποτυπώνουμε το διαμέρισμα, εξετάζουμε τις τεχνικές δυνατότητες και μελετάμε διαρρύθμιση, υλικά και φωτισμό. Οι κατόψεις και τα renders κάνουν τις επιλογές ορατές πριν ξεκινήσουν οι εργασίες.'),
           ('Οργανώνουμε τη δημιουργία', 'Συμφωνούμε το αντικείμενο, τον προϋπολογισμό και το πλάνο εργασιών. Συντονίζουμε την υλοποίηση και συζητάμε τις αλλαγές μαζί σου, με καθαρή εικόνα για την επίδρασή τους στο έργο.'),
           ('Παραδίδουμε και φροντίζουμε', 'Ελέγχουμε το αποτέλεσμα και καταγράφουμε όσα χρειάζονται ολοκλήρωση. Μετά την παράδοση, παραμένουμε σημείο επικοινωνίας για υποστήριξη, σύμφωνα με τους όρους του έργου.')]
    body = ('<main id="main">' + intro('Η εταιρεία μας · Ποιοι είμαστε', 'Δημιουργούμε χώρους.<br><em>Ανοίγουμε δυνατότητες.</em>',
                                      'Η Arcus Development αναλαμβάνει ολικές ανακαινίσεις διαμερισμάτων, από τη μελέτη και τον σχεδιασμό μέχρι την κατασκευή και την παράδοση.', more('#why', 'Το γιατί μας'))
            + subnav('/el/etaireia', links)
            + f'<section class="sec wrap manifesto" id="why">{eyebrow("01 — Γιατί δημιουργούμε")}<h2>Σχεδιάζουμε χώρους<br><em>γύρω από τη ζωή σου.</em></h2>'
            f'<p class="manifesto-text">{WHY}</p><p class="lede">Μια νέα αρχή για το σπίτι σου. Μια νέα προοπτική για ένα ακίνητο που περιμένει να αξιοποιηθεί. Η ανακαίνιση αποκτά αξία όταν υπηρετεί αυτό που θέλεις να γίνει η επόμενη μέρα.</p></section>'
            + f'<figure class="wrap wide-figure">{pic("/assets/portfolio/soulioti-17/home-kitchen-light.webp", "Ανακαινισμένη κουζίνα της Arcus Development με ξύλο, ανθρακί επιφάνειες και φυσικό φως", sizes="100vw")}<figcaption>Από την ιδέα στον χώρο που ζεις — ολοκληρωμένο έργο Arcus Development.</figcaption></figure>'
            + '<section class="sec wrap" id="how">' + head('02 — Πώς δουλεύουμε', 'Η φαντασία δίνει κατεύθυνση.<br><em>Η μελέτη δίνει μορφή.</em>', 'Συνδέουμε τη δημιουργικότητα με την τεχνική σκέψη και την οργανωμένη υλοποίηση. Κάθε απόφαση χρειάζεται να υπηρετεί την ίδια ιδέα.')
            + steps(how, 'steps steps-4') + f'<div class="row-links">{more("/el/diadikasia", "Δες τη διαδικασία μας")}{more("/el/filosofia", "Οι αξίες μας στην πράξη")}</div></section>'
            + '<section class="sec sec-tint" id="what"><div class="wrap">' + head('03 — Τι κάνουμε', 'Ολικές ανακαινίσεις.<br><em>Με τον δικό σου σκοπό.</em>', 'Εστιάζουμε στην ολική ανακαίνιση διαμερισμάτων: από την αποτύπωση και τη μελέτη μέχρι την κατασκευή και την παράδοση. Για το σπίτι που θέλεις να ζήσεις ή για την αξιοποίηση του ακινήτου σου.')
            + paths() + '</div></section>'
            + f'<section class="sec wrap prose-split"><div>{eyebrow("Μέλος του Arcus Group")}<h2>Κοινές αξίες.<br><em>Η δική μας δημιουργική έκφραση.</em></h2></div><div class="prose">'
            '<p>Μοιραζόμαστε με την Arcus την εμπιστοσύνη, την ακεραιότητα, την ποιότητα, τη συνεργασία και την καινοτομία. Στην Development, οι αξίες αυτές παίρνουν μορφή σε μια κάτοψη, σε μια τεχνική επιλογή, στη συνεννόηση και στη φροντίδα του έργου.</p>'
            '<p>Μέσα από το δίκτυο του ομίλου, συνδέουμε την ανακαίνιση με τις ανάγκες πριν και μετά: αγορά, εκτίμηση, μίσθωση και διαχείριση.</p>'
            + more('/el/one-stop-shop', 'Γνώρισε το One Stop Shop') + '</div></section>' + finalcta() + '</main>')
    page('etaireia', 'Ποιοι είμαστε — Γιατί, Πώς, Τι | Arcus Development', 'Γιατί δημιουργούμε, πώς δουλεύουμε και τι αναλαμβάνουμε. Η φιλοσοφία της Arcus Development στην ολική ανακαίνιση διαμερισμάτων.', body)

    # Philosophy and values
    values = [('Εμπιστοσύνη', 'Η δημιουργία χρειάζεται καθαρή συνεννόηση.', 'Συζητάμε το αντικείμενο και τις επιλογές με τρόπο κατανοητό. Εξηγούμε τι περιλαμβάνει η πρόταση και τι χρειάζεται ξεχωριστή συμφωνία.'),
              ('Ακεραιότητα', 'Η σωστή απόφαση ξεκινά από την αλήθεια.', 'Ελέγχουμε τις δυνατότητες του ακινήτου πριν προτείνουμε παρεμβάσεις. Ο διαχωρισμός εξετάζεται με βάση τις τεχνικές και νομικές προϋποθέσεις κάθε έργου· η απόδοση μιας επένδυσης δεν προεξοφλείται.'),
              ('Ποιότητα', 'Το αποτέλεσμα κρίνεται και στην καθημερινή χρήση.', 'Συνδέουμε την αισθητική με τη λειτουργικότητα, τα υλικά και τις λεπτομέρειες εφαρμογής. Δίνουμε προσοχή τόσο σε όσα φαίνονται όσο και στις υποδομές που στηρίζουν τον χώρο.'),
              ('Συνεργασία', 'Η καλύτερη ιδέα εξελίσσεται μαζί.', 'Η γνώση σου για τον τρόπο που ζεις συναντά τη μελέτη και την εμπειρία των συνεργείων. Συντονίζουμε τις διαφορετικές ειδικότητες γύρω από έναν κοινό στόχο.'),
              ('Καινοτομία', 'Κάθε περιορισμός είναι αφορμή για νέα σκέψη.', 'Εξερευνούμε εναλλακτικές διαρρυθμίσεις και αξιοποιούμε την τρισδιάστατη απεικόνιση για πιο ξεκάθαρες επιλογές. Επιλέγουμε λύσεις επειδή προσφέρουν ουσία στον χώρο.'),
              ('Δημιουργικότητα', 'Ο χώρος σου χρειάζεται τη δική σου υπογραφή.', 'Σχεδιάζουμε με αφετηρία τις ανάγκες και τις επιθυμίες σου. Το φως, οι υφές και οι αναλογίες συνθέτουν ένα σύνολο με χαρακτήρα και σκοπό.')]
    body = ('<main id="main">' + intro('Η εταιρεία μας · Φιλοσοφία & αξίες', 'Όσα πιστεύουμε.<br><em>Σε όσα δημιουργούμε.</em>',
                                      'Οι κοινές αξίες της Arcus καθοδηγούν τον τρόπο που συνεργαζόμαστε. Η δημιουργικότητα είναι ο τρόπος που τις εκφράζουμε στον χώρο.')
            + subnav('/el/filosofia', links)
            + f'<section class="sec wrap manifesto">{eyebrow("Το γιατί μας")}<h2>Πρώτα ο άνθρωπος.<br><em>Έπειτα η κάτοψη.</em></h2><p class="manifesto-text">{WHY}</p>{more("/el/etaireia#how", "Πώς γίνεται πράξη")}</section>'
            + '<section class="sec sec-tint"><div class="wrap">' + head('Οι αξίες μας στην πράξη', 'Αρχές που καθοδηγούν<br><em>κάθε απόφαση.</em>')
            + '<ol class="values">' + ''.join(f'<li><p class="value-name"><span>{i + 1:02d}</span>{t}</p><h3>{h}</h3><p>{d}</p></li>' for i, (t, h, d) in enumerate(values)) + '</ol></div></section>'
            + f'<section class="sec wrap prose-split"><div>{eyebrow("Από το γιατί στο αποτέλεσμα")}<h2>Η φιλοσοφία φαίνεται<br><em>στα έργα μας.</em></h2></div><div class="prose">'
            '<p>Δες τις πραγματικές μεταμορφώσεις: την αρχική κατάσταση, τις σχεδιαστικές επιλογές και το αποτέλεσμα κάθε ανακαίνισης, με το διαθέσιμο υλικό του έργου.</p>'
            + more('/el/erga', 'Εξερεύνησε τα έργα μας') + '</div></section>' + finalcta() + '</main>')
    page('filosofia', 'Φιλοσοφία & αξίες | Arcus Development', 'Οι κοινές αξίες της Arcus και η δημιουργική τους έκφραση στη μελέτη, τη συνεργασία και την ολική ανακαίνιση διαμερισμάτων.', body)

    # FAQ
    extra = [('Η μελέτη παρέχεται δωρεάν;', 'Η αρχική επικοινωνία βοηθά να καταγράψουμε τον στόχο. Το αντικείμενο και η αμοιβή αποτύπωσης, ελέγχου, μελέτης και renders συμφωνούνται πριν από την ανάθεση.'),
             ('Μπορώ να επιλέξω δικά μου υλικά;', 'Συζητάμε τις επιλογές σου σε συνδυασμό με τις τεχνικές απαιτήσεις και τον συμφωνημένο προϋπολογισμό.'),
             ('Πώς υποβάλλω ζήτημα μετά την παράδοση;', 'Χρησιμοποίησε την επιλογή after-sales στη φόρμα επικοινωνίας ή κάλεσε στο 2310 445 935. Συμπλήρωσε τη γενική περιοχή, περιγραφή και προαιρετικές φωτογραφίες.'),
             ('Αναλαμβάνετε μεμονωμένες μικροεργασίες;', 'Εστιάζουμε στην ολική ανακαίνιση διαμερισμάτων για κατοικία ή επενδυτική αξιοποίηση. Η μελέτη, τα renders και η κατασκευή συνδέονται σε αυτή την ολοκληρωμένη εμπειρία.')]
    body = ('<main id="main">' + intro('Οδηγός · Συχνές ερωτήσεις', 'Μια καθαρή εικόνα.<br>Πριν από <em>την πρώτη απόφαση.</em>', 'Όσα χρειάζεται να γνωρίζεις για τη μελέτη, το κόστος, την υλοποίηση και τη φροντίδα του έργου.')
            + subnav('/el/sychnes-erotiseis', links)
            + '<section class="sec wrap faq-wrap"><div class="faq-head"><h2>Δεν βρήκες<br><em>την απάντηση;</em></h2><p>Κάλεσε στο <a href="tel:+302310445935">2310 445 935</a> ή γράψε μας.</p>' + more('/el/epikoinonia', 'Ρώτησε την ομάδα') + '</div>'
            + faq(basefaq + extra) + '</section>' + finalcta() + '</main>')
    page('sychnes-erotiseis', 'Συχνές Ερωτήσεις | Arcus Development', 'Απαντήσεις για το κόστος, τη μελέτη, τα υλικά και τα στάδια ολικής ανακαίνισης διαμερίσματος από την Arcus Development.', body)

    # Glossary: the terms stay in the approved legacy page; we read them from there.
    src = (root / 'site/legacy/glossary.html').read_text()
    terms = re.findall(r'<div class="term-entry" data-category="(\w+)"><dt>(.*?)</dt><dd><span class="term-category">(.*?)</span><p>(.*?)</p></dd></div>', src)
    body = ('<main id="main">' + intro('Η εταιρεία μας · Τεχνικό λεξικό', 'Μια κοινή γλώσσα<br>για τη <em>δημιουργία.</em>', 'Οι λέξεις που συναντάμε σε ένα έργο, με απλές εξηγήσεις. Για να συζητάμε τις επιλογές με περισσότερη σαφήνεια.')
            + subnav('/el/techniko-lexiko', links)
            + '<section class="sec-tight wrap glossary"><div class="glossary-tools" hidden><label for="term-search">Ποιον όρο αναζητάς;</label>'
            '<div class="search"><input id="term-search" type="search" placeholder="π.χ. κάτοψη, υλικά, φωτισμός" autocomplete="off"><button id="clear-search" type="button" hidden>Καθαρισμός</button></div>'
            '<div class="segmented" role="group" aria-label="Φίλτρο θεματικής"><button type="button" data-filter="all" aria-pressed="true">Όλοι</button><button type="button" data-filter="design" aria-pressed="false">Σχεδιασμός</button>'
            '<button type="button" data-filter="build" aria-pressed="false">Κατασκευή</button><button type="button" data-filter="planning" aria-pressed="false">Οργάνωση έργου</button></div>'
            f'<p id="term-count" role="status" aria-live="polite">{len(terms)} όροι</p></div>'
            '<dl class="terms">' + ''.join(f'<div class="term-entry" data-category="{c}"><dt>{t}</dt><dd><span>{cat}</span><p>{d}</p></dd></div>' for c, t, cat, d in terms) + '</dl>'
            '<div class="empty-terms" hidden><h2>Δεν βρέθηκε κάποιος όρος.</h2><p>Δοκίμασε μια πιο σύντομη λέξη ή διαφορετική θεματική.</p><button class="btn btn-ghost" id="reset-terms" type="button">Εμφάνιση όλων των όρων</button></div>'
            '<p class="fine">Οι εξηγήσεις βοηθούν στην κατανόηση της ορολογίας. Οι τεχνικές επιλογές για κάθε έργο προκύπτουν από τη δική του μελέτη.</p></section>'
            + finalcta() + '</main>')
    page('techniko-lexiko', 'Τεχνικό Λεξικό | Arcus Development', 'Κατόψεις, αποτύπωση, renders και όροι ανακαίνισης σε απλά ελληνικά. Ένας πρακτικός οδηγός από την Arcus Development.', body)
